async function roll(){if(busy||$('#menu-drawer').open||$('#content-dialog').open)return;busy=true;fight.cancel();const token=++lastRoll;const p={...draw(zonePool(state.zone)),shiny:rollShiny()};const isNewForm=!formCount(state,p.id,p.shiny);const isNew=!state.counts[p.id];const dataPromise=details(p.id).catch(()=>null);$('#roll').hidden=false;$('#roll').disabled=true;$('#result').hidden=true;$('#roll-cta').disabled=true;$('#stage').classList.add('rolling');$('#result-name').hidden=false;$('#result-details').hidden=true;$('#hp').hidden=true;$('#result-name').textContent='Quelque chose se prépare…';$('#result-details').textContent='La prochaine rencontre est peut-être la bonne.';renderZones();await new Promise(r=>setTimeout(r,state.reducedMotion?150:850));const prev=state.counts[p.id]||0;const encounterTraining=createTraining();if(!state.training[p.id])state.training[p.id]=encounterTraining;recordForm(state,p.id,p.shiny);state.history.unshift(p.id);state.history=state.history.slice(0,5);state.historyShiny.unshift(p.shiny);state.historyShiny=state.historyShiny.slice(0,5);if(isNew)state.team=teamAfterCapture(state.team,p.id);save();busy=false;render();$('#stage').classList.remove('rolling');$('#roll').hidden=true;$('#roll').disabled=false;$('#result').hidden=false;const after=levelInfo(p.id,prev+1),before=prev?levelInfo(p.id,prev):null;const tag=p.shiny?(isNewForm?'✦ NOUVEAU CHROMATIQUE · 1 / 4 096':'✦ CHROMATIQUE · 1 / 4 096'):isNew?'✦ NOUVELLE DÉCOUVERTE':after.level>before.level?`▲ NIVEAU ${after.level}`:after.capped?'NIVEAU MAX DU STADE':'DOUBLON · +1 XP';$('#result').innerHTML=`<img src="${sprite(p.id,p.shiny)}" alt="${p.name}${p.shiny?' chromatique':''}"><small>${tag}</small>`;$('#result').classList.toggle('is-shiny',p.shiny);$('#result-name').textContent=p.name+(p.shiny?' ✦ Chromatique':'');$('#result-details').hidden=false;$('#result-details').textContent=`✦ ${p.power} puissance · ${odds(p)} dans cette zone`;fight.start(p,types[p.id],encounterTraining);$('#stage-caption').textContent='CHOISIS UNE ATTAQUE · ESPACE POUR FUIR';$('#roll-cta').textContent='Fuir et relancer · Espace';$('#roll-cta').disabled=false;const data=await dataPromise;if(token===lastRoll&&!p.shiny&&data?.sprites?.front_default){const img=$('#result img');if(img)img.src=data.sprites.front_default;}}
$('#roll').onclick=roll;$('#result').onclick=()=>{if(!fight.active())roll();};$('#roll-cta').onclick=roll;document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['BUTTON','A','INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!$('#menu-drawer').open&&!$('#content-dialog').open){e.preventDefault();roll();}});
